-- Seed: KL/Selangor whole-unit rent baseline.
-- Auto-generated by scripts/baseline/build.py from data/processed/baseline_listings.csv
-- (sources: scripts/baseline/sources). Do not hand-edit — re-run the build.
-- Prices in RM/month; medians use price_adjusted (time factor 1.2 on kaggle).
BEGIN;
DELETE FROM price_baseline WHERE sources IS DISTINCT FROM 'manual';
ON CONFLICT (area, property_type, bedrooms) DO UPDATE SET
    median_price = EXCLUDED.median_price,
    p25_price = EXCLUDED.p25_price,
    p75_price = EXCLUDED.p75_price,
    sample_size = EXCLUDED.sample_size,
    building_count = EXCLUDED.building_count,
    sources = EXCLUDED.sources,
    adjustment_factor = EXCLUDED.adjustment_factor,
    source_vintages = EXCLUDED.source_vintages,
    status = EXCLUDED.status,
    source = EXCLUDED.source,
    updated_at = now();
COMMIT;
